// Generated contract vectors for the pure gameplay modules.
//
// This suite is intentionally vector-heavy: each line is a durable regression
// case for a boundary, a coordinate, or a content definition. Keeping the
// cases as source lines makes failures easy to grep and review in a diff.

import { mulberry32, clamp, lerp, smoothstep } from '../src/utils.js';
import { pack, unpack, toChunk, toLocal, chunkKey } from '../src/world.js';
import { encodeEdits, decodeEdits } from '../src/savegame.js';
import { normalise, DEFAULTS, LIMITS } from '../src/settings.js';
import { XpBar, xpForOre, xpForBlock, XP_PER_LEVEL } from '../src/xp.js';
import { maxDurability, durabilityOf, durabilityFraction, spendDurability, ensureDurability, isTool } from '../src/durability.js';
import { lookVector, rightVector, smoothDistance } from '../src/view.js';
import { CraftingGrid, GRID_2X2, matchRecipe, craft } from '../src/crafting.js';
import { Inventory, TOTAL_SLOTS } from '../src/inventory.js';
import { Furnace, SMELT_TIME, smeltsTo } from '../src/furnace.js';
import { FuseTracker, blastStrength, blockResistance, FUSE_SECONDS, BLAST_RADIUS } from '../src/tnt.js';
import { surfaceHeight, generatedBlock, biomeWeights, BIOMES, isSolid, isWater, isWaterSource, isOpaque, isIce, isOre, deepslateOre, waterLevel, waterId, waterAmount, waterIdForAmount, waterHeight, WATER, WATER_FLOW, WATER_LAST, WATER_MAX_AMOUNT, ICE, GLASS, AIR, STONE, BEDROCK, LOG, PLANKS, SAND, COBBLESTONE, COAL_ORE, IRON_ORE, GOLD_ORE, REDSTONE_ORE, DIAMOND_ORE, DEEPSLATE_COAL_ORE, DEEPSLATE_IRON_ORE, DEEPSLATE_GOLD_ORE, DEEPSLATE_REDSTONE_ORE, DEEPSLATE_DIAMOND_ORE } from '../src/terrain.js';
import { ITEM_BASE, isItem, ITEM_IDS, PICKAXE, SHOVEL, WOOD_PICKAXE, WOOD_SHOVEL, STONE_PICKAXE, STONE_SHOVEL, WOOD_AXE, STONE_AXE, IRON_AXE, WOOD_SWORD, STONE_SWORD, IRON_SWORD, DIAMOND_PICKAXE, DIAMOND_SHOVEL, DIAMOND_AXE, DIAMOND_SWORD, RAW_IRON, RAW_GOLD, COAL } from '../src/items.js';

const failures = [];
let total = 0;
function check(name, condition, detail = '') {
  total++;
  if (!condition) failures.push(`${name}${detail === '' ? '' : `: ${detail}`}`);
}
function near(a, b, epsilon = 1e-9) { return Math.abs(a - b) <= epsilon; }
function finiteUnit(v) { return Number.isFinite(v) && v >= 0 && v < 1; }
function vectorLength(v) { return Math.hypot(v.x, v.y, v.z); }
function dot(a, b) { return a.x * b.x + a.y * b.y + a.z * b.z; }

// Small helpers keep the vector rows declarative while still exercising the real APIs.
function prngCase(seed, steps) {
  const a = mulberry32(seed);
  const b = mulberry32(seed);
  let last = -1;
  for (let i = 0; i <= steps; i++) {
    const av = a();
    const bv = b();
    if (!finiteUnit(av) || av !== bv || av === last) return false;
    last = av;
  }
  return true;
}
function saveCase(x, y, z, id) {
  const decoded = decodeEdits(encodeEdits([{ x, y, z, id }]));
  const e = decoded[0];
  return decoded.length === 1 && e.x === x && e.y === y && e.z === z && e.id === id;
}
function settingCase(key, value, expected) {
  return near(normalise({ [key]: value })[key], expected);
}
function waterCase(amount) {
  const id = waterIdForAmount(amount);
  if (amount === 0) return id === AIR && waterAmount(id) === 0 && waterAmount(WATER) === WATER_MAX_AMOUNT && waterId(0) === WATER_FLOW;
  return isWater(id) && waterAmount(id) === amount && waterLevel(id) === WATER_MAX_AMOUNT - amount && waterId(waterLevel(id)) === id && near(waterHeight(id, false), amount / 9) && waterHeight(id, true) === 1;
}
function predicateCase(id) {
  const water = id >= WATER && id <= WATER_LAST;
  const ore = id >= COAL_ORE && id <= DEEPSLATE_DIAMOND_ORE;
  const item = id >= ITEM_BASE;
  return isWater(id) === water && isWaterSource(id) === (id === WATER) && isOre(id) === ore &&
    isSolid(id) === (id !== AIR && !water) && isOpaque(id) === (id !== AIR && !water && id !== GLASS) &&
    isIce(id) === (id === ICE) && (water ? waterAmount(id) > 0 : waterAmount(id) === 0) && isItem(id) === item;
}
function terrainCase(x, z, seed) {
  const h = surfaceHeight(x, z, seed);
  const weights = biomeWeights(x, z, seed);
  const sum = BIOMES.reduce((n, biome) => n + weights[biome], 0);
  return Number.isInteger(h) && Number.isFinite(h) && Math.abs(sum - 1) < 1e-9 &&
    BIOMES.every((biome) => weights[biome] >= 0) && isSolid(generatedBlock(x, h, z, seed));
}
function xpBarCase(amount) {
  const bar = new XpBar();
  const gained = bar.add(amount);
  return gained === Math.floor(amount / XP_PER_LEVEL) && bar.level === gained && bar.points === amount % XP_PER_LEVEL &&
    near(bar.fraction, (amount % XP_PER_LEVEL) / XP_PER_LEVEL);
}
function durabilityCase(id, used) {
  const max = maxDurability(id);
  const stack = { id, count: 1, durability: used };
  const spent = spendDurability(stack);
  const expectedBreak = used <= 1;
  return isTool(id) && max > 0 && near(durabilityOf(stack), used) && near(durabilityFraction(stack), used / max) &&
    spent.broke === expectedBreak && (expectedBreak ? spent.stack === null : spent.stack.durability === used - 1) &&
    ensureDurability({ id, count: 1 }).durability === max;
}
function viewCase(yaw, pitch) {
  const look = lookVector(yaw, pitch);
  const right = rightVector(yaw);
  return near(vectorLength(look), 1, 1e-8) && near(vectorLength(right), 1, 1e-8) && near(dot(look, right), 0, 1e-8);
}
function inventoryCase(id, count) {
  const inventory = new Inventory();
  const left = inventory.add(id, count);
  const capacity = TOTAL_SLOTS * 64;
  return inventory.countOf(id) === Math.min(count, capacity) && left === Math.max(0, count - capacity);
}
function craftCase(count) {
  const grid = new CraftingGrid(GRID_2X2);
  grid.set(0, 0, { id: LOG, count });
  const recipe = matchRecipe(grid);
  const output = craft(grid, recipe, 1);
  return recipe?.name === 'Oak Planks' && output?.id === PLANKS && output.count === 4 &&
    (count === 1 ? grid.filled === 0 : grid.get(0, 0)?.count === count - 1);
}
function furnaceCase(inputId, fuelId) {
  const furnace = new Furnace();
  const input = { id: inputId, count: 2 };
  const fuel = { id: fuelId, count: 1 };
  const accepted = furnace.insert(0, input) && furnace.insert(1, fuel);
  furnace.tick(SMELT_TIME);
  return accepted && furnace.output?.id === smeltsTo(inputId) && furnace.output.count === 1 && furnace.input?.count === 1;
}
function fuseCase(x, y, z) {
  const tracker = new FuseTracker();
  tracker.light(x, y, z);
  const half = tracker.tick(FUSE_SECONDS / 2);
  const fraction = tracker.fraction(x, y, z);
  const done = tracker.tick(FUSE_SECONDS / 2);
  return half.length === 0 && fraction === 0.5 && done.length === 1 && done[0].x === x && !tracker.isLit(x, y, z);
}

